def bst_sum_range(root, low, high):
    if root is None:
        return 0
    if root.key < low:
        return bst_sum_range(root.right, low, high)
    if root.key > high:
        return bst_sum_range(root.left, low, high)
    return root.key + bst_sum_range(root.left, low, high) + bst_sum_range(root.right, low, high)

def bst_contains(root, x):
    if root is None:
        return False
    if x == root.key:
        return True
    elif x < root.key:
        return bst_contains(root.left, x)
    else:
        return bst_contains(root.right, x)

def tree_height(root):
    if root is None:
        return -1
    left_h = tree_height(root.left)
    right_h = tree_height(root.right)
    return 1 + max(left_h, right_h)

